import { bar } from 'axylo';

// One series per region (wide rows: one row per quarter, one field per region).
const REGIONS = [
  { field: 'north', label: 'North' },
  { field: 'central', label: 'Central' },
  { field: 'west', label: 'West' },
];

/**
 * Chronological sort key for labels such as "2025 Q3", or null when a label has another form.
 * @param {unknown} label
 * @returns {number | null}
 */
function quarterKey(label) {
  const match = /^\s*(\d{4})\s*Q([1-4])\s*$/i.exec(String(label));
  return match ? Number(match[1]) * 4 + (Number(match[2]) - 1) : null;
}

/**
 * Rows in calendar order. Axylo reads quarters as categories (1.0 has no quarter type), and
 * categories keep the order in which they first appear, so the rows must arrive in time order.
 * Copies the array; the caller's rows and row objects are left untouched.
 * @param {readonly Record<string, unknown>[]} rows
 */
function inQuarterOrder(rows) {
  return [...rows].sort((a, b) => {
    const ka = quarterKey(a?.quarter);
    const kb = quarterKey(b?.quarter);
    if (ka === null || kb === null) return (ka === null ? 1 : 0) - (kb === null ? 1 : 0);
    return ka - kb;
  });
}

/**
 * The bar chart's options for the given rows. Exported so the same options can be checked
 * with `validate('bar', ...)` in Node.
 * @param {readonly Record<string, unknown>[]} data
 */
export function chartOptions(data) {
  return {
    title: 'Quarterly sales by region',
    data: Array.isArray(data) ? inQuarterOrder(data) : data,
    // Quarters are ordered categories, as the docs advise for calendar periods other than years and months.
    x: { field: 'quarter', type: 'category', ordered: true },
    // The sales figures arrive as decimal strings ("1580.75"): declare the conversion to numbers.
    y: REGIONS.map(({ field, label }) => ({ field, label, parse: 'number' })),
    // Several fields share one value axis, which Axylo titles "Value" by default; name what it measures.
    messages: { value: 'Sales' },
  };
}

/**
 * Draw the chart into `element` and return the Axylo chart handle.
 * @param {HTMLElement} element
 * @param {readonly Record<string, unknown>[]} data rows from data.json
 */
export default function render(element, data) {
  return bar(element, chartOptions(data));
}

