input.command:
node --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render, { chartOptions } from './chart.js';

const rows = JSON.parse(readFileSync('data.json', 'utf8'));
const before = JSON.stringify(rows);
const opts = chartOptions(rows);

console.log('render is default function:', typeof render === 'function', 'arity', render.length);
console.log('order:', opts.data.map(r => r.quarter).join(' | '));
console.log('input unchanged:', JSON.stringify(rows) === before);
console.log('same row objects:', opts.data.every(r => rows.includes(r)));

const problems = validate('bar', opts);
console.log('diagnostics:', problems.length);
for (const d of problems) console.log(' ', d.code, d.level, d.field ?? '', '-', d.message);

// Control: without parse, what would Axylo say? (confirms the parse option is what silences AX104)
const noParse = validate('bar', { ...opts, y: opts.y.map(({ parse, ...f }) => f) });
console.log('control without parse:', noParse.map(d => d.code + ' ' + d.level).join(', ') || 'none');
"

